import{c as o,Q as e,j as n,m as s}from"./chunks/framework.BXc4yaFE.js";const d=JSON.parse('{"title":"Anthropic 工程师70分钟workshop 教你如何让Agent自我优化式的工作","description":"","frontmatter":{"url":"https://x.com/easycompany333/status/2070096665403650233","title":"Anthropic 工程师70分钟workshop 教你如何让Agent自我优化式的工作","author":"Easycompany","archived":"2026-06-27T00:00:00.000Z","duration":"01:10:22","handle":"@Easycompany333","published":"2026-06-25T00:00:00.000Z","subtitle_lang":"Chinese (混合英語)","type":"video"},"headers":[],"relativePath":"research/tweets/2026-06-25-easycompany333-2070096665403650233.md","filePath":"research/tweets/2026-06-25-easycompany333-2070096665403650233.md","lastUpdated":1785909234000}'),r={name:"research/tweets/2026-06-25-easycompany333-2070096665403650233.md"};function a(i,t,l,g,p,h){return e(),n("div",null,[...t[0]||(t[0]=[s('<h1 id="anthropic-工程师70分钟workshop-教你如何让agent自我优化式的工作-—-easycompany333" tabindex="-1">Anthropic 工程师70分钟workshop 教你如何让Agent自我优化式的工作 — @Easycompany333 <a class="header-anchor" href="#anthropic-工程师70分钟workshop-教你如何让agent自我优化式的工作-—-easycompany333" aria-label="Permalink to &quot;Anthropic 工程师70分钟workshop 教你如何让Agent自我优化式的工作 — @Easycompany333&quot;">​</a></h1><p><strong>來源</strong>: <a href="https://x.com/easycompany333/status/2070096665403650233" target="_blank" rel="noreferrer">https://x.com/easycompany333/status/2070096665403650233</a><strong>作者</strong>: Easycompany (@Easycompany333) <strong>發布日期</strong>: 2026-06-25 <strong>收錄日期</strong>: 2026-06-27 <strong>時長</strong>: 01:10:22 <strong>語言</strong>: 中文（夾雜英語，為 Anthropic 英語 workshop 的中文字幕版）</p><hr><h2 id="核心摘要" tabindex="-1">核心摘要 <a class="header-anchor" href="#核心摘要" aria-label="Permalink to &quot;核心摘要&quot;">​</a></h2><blockquote><p>此影片為 Anthropic engineer conference workshop 的中文字幕版（與 vmlops 版本為同一場次）：Anthropic 工程師 Andrew 與 Ash 揭示如何設計讓 Agent 自我優化運行數天的 harness 架構，核心是 Generator-Evaluator 對抗式評估迴圈。</p></blockquote><ul><li><strong>Agent 長時運行三大障礙</strong>：Context 有限（記憶重置、Context Rot、Context Sense Anxiety）、規劃能力弱、模型無法準確自我評估輸出品質</li><li><strong>模型能力里程碑</strong>：從 Sonnet 3.7（1 小時）→ Sonnet 4.5（30 小時）→ Opus 4.6（12 小時基準 / 實際可更長），模型與 harness 共同演化</li><li><strong>核心架構：Planner + Generator + Evaluator 三角</strong>：Planner 產生高階 sprint 規劃；Generator/Evaluator 在開始建構前協商「完成條件契約（Done Contract）」；Evaluator 以獨立 context window 進行對抗性評估，甚至使用 Playwright 實際操作 app</li><li><strong>品味可量化</strong>：UI 設計以 Design / Originality / Craft / Functionality 四維評分，設定強觀點的 rubric 能顯著提升輸出品質，防止 AI slop</li><li><strong>Opus 4.6 帶來簡化</strong>：原本複雜的 per-sprint 評估在 Opus 4.6 下可簡化為單 session 連續建構，server-side compaction 讓 agent 可無限運行</li></ul><hr><h2 id="整理版-可讀逐字稿" tabindex="-1">整理版（可讀逐字稿） <a class="header-anchor" href="#整理版-可讀逐字稿" aria-label="Permalink to &quot;整理版（可讀逐字稿）&quot;">​</a></h2><h3 id="背景-claude-code-的一年演化-00-00–01-18" tabindex="-1">背景：Claude Code 的一年演化（00:00–01:18） <a class="header-anchor" href="#背景-claude-code-的一年演化-00-00–01-18" aria-label="Permalink to &quot;背景：Claude Code 的一年演化（00:00–01:18）&quot;">​</a></h3><p>Andrew 介紹本次 workshop 是 engineer conference 首場 session。他引用 Boris（Claude Code 創始人）在一週年時的感言：一年前 Claude 還在為 bash 命令掙扎、只能跑 20 分鐘；現在幾乎所有 Claude Code 都是 Claude Code 自己寫的，且能持續數天運行。</p><h3 id="agent-長時運行的三大挑戰-01-18–02-46" tabindex="-1">Agent 長時運行的三大挑戰（01:18–02:46） <a class="header-anchor" href="#agent-長時運行的三大挑戰-01-18–02-46" aria-label="Permalink to &quot;Agent 長時運行的三大挑戰（01:18–02:46）&quot;">​</a></h3><p><strong>挑戰一：Context 限制</strong></p><ul><li>Context window 有限：新 session 等於失憶，必須有記憶組件</li><li>Context Rot：越深入 session，連貫性越差</li><li>Context Sense Anxiety：模型接近 context 上限時會緊張地匆忙收尾</li></ul><p><strong>挑戰二：規劃能力不足</strong></p><ul><li>模型傾向一次性完成所有事，或做到一半停下</li><li>可能建了 UI button 但 backend 完全不存在</li></ul><p><strong>挑戰三：自我評估失準</strong></p><ul><li>模型傾向告訴你想聽的話，看到半成品也可能認為「完成了」</li></ul><h3 id="兩大解法-改善模型-vs-改善-harness-02-46–15-18" tabindex="-1">兩大解法：改善模型 vs 改善 Harness（02:46–15:18） <a class="header-anchor" href="#兩大解法-改善模型-vs-改善-harness-02-46–15-18" aria-label="Permalink to &quot;兩大解法：改善模型 vs 改善 Harness（02:46–15:18）&quot;">​</a></h3><p><strong>解法一：改善模型本身</strong> 「meter chart」展示 agent 在最簡 scaffold 下完成 50% 任務的時間：</p><ul><li>Opus 3.7：約 1 小時</li><li>Sonnet 4.5：約 30 小時（配合 Claude Code 2.0 checkpoints）</li><li>Opus 4.6：約 12 小時基準（實際已實現更長）</li></ul><p><strong>解法二：改善 Harness</strong> Anthropic Agent SDK 提供核心原語：agent loop、MCP server、sub-agent 委派、Claude.md/skills/slash commands、權限系統。</p><p>技術里程碑回顧：</p><ul><li><strong>Computer Use</strong>：能截圖、點擊、自測程式碼</li><li><strong>Claude Code（Feb 2025）</strong>：Sonnet 3.7，最初定位為實驗性工具</li><li><strong>Ralph Loop</strong>：「可預測失敗優於不可預測成功」——planning phase → 拆分 features → 各開新 session 工作</li><li><strong>Claude Code 2.0</strong>：Checkpoints + context-aware tracking</li><li><strong>Haiku 4.5 完成家族</strong>：sub-agent 在經濟上可行，開始大規模使用</li><li><strong>Sonnet 4.6 + Opus 4.6</strong>：Opus 4.6 定義為最強 agentic 模型；Agent Teams（sub-agent 互通）；Server-side Compaction（無限運行）；1M context GA</li></ul><h3 id="ash-接棒-generator-evaluator-對抗式-harness-15-18–36-38" tabindex="-1">Ash 接棒：Generator-Evaluator 對抗式 Harness（15:18–36:38） <a class="header-anchor" href="#ash-接棒-generator-evaluator-對抗式-harness-15-18–36-38" aria-label="Permalink to &quot;Ash 接棒：Generator-Evaluator 對抗式 Harness（15:18–36:38）&quot;">​</a></h3><p><strong>為什麼不能自我評估？</strong></p><p>就像批評一道菜比自己烹飪容易——訓練一個「嚴格的 standalone critic」比要求 builder 自我批評有效得多。</p><p><strong>品味量化</strong>： Anthropic 的四維評分 rubric（Design / Originality / Craft / Functionality），使用者可根據模型特性調整權重（Opus 4.6 功能性已強，更強調 Design + Originality）。用參考網站校準評估器的品味，防止 AI slop。</p><p>GAN 式 harness 的關鍵優勢：當 Generator 在某維度持續低分（如 originality），harness 直接丟棄重來——這是 single agent loop 或 Ralph Loop 做不到的。</p><p><strong>Planner + Generator + Evaluator 完整架構</strong>：</p><ol><li><strong>Planner</strong>：一行提示 → 高階 sprint 清單（刻意不細化技術，避免早期錯誤沿 sprint 級聯放大）</li><li><strong>Done Contract 協商</strong>：Generator 建構前，Generator 提出測試方案，Evaluator 可能回推「scope 太大、測試太弱」，雙方協商出明確完成條件</li><li><strong>Generator 建構</strong>：Evaluator 對照 Done Contract 評分，而非原始 spec</li><li><strong>Playwright 實際測試</strong>：只有真正使用 app 才能發現的 bug（如 button 有 UI 但 backend 不存在）</li></ol><p><strong>真實案例：Retro Game Maker</strong></p><ul><li>單行提示：「build a retro game maker」</li><li>Harness 自動加入 AI assistant 功能（Planner 從 spec 中的「some AI features」推導）</li><li>Evaluator 測試出的問題（如「音符播放但遊戲還在跑」「沒有 undo 功能」）只有使用 app 才能發現</li></ul><p><strong>DAW（數位音訊工作站）案例</strong>：Agent 設定節拍、鋪設旋律、建構鼓軌。Claude 無法「聽到」音樂，所以音樂本身很差，但 app 本身完成度很高，是 Opus 4.6 以前根本無法完成的任務。</p><h3 id="opus-4-6-帶來的架構簡化-28-00–36-38" tabindex="-1">Opus 4.6 帶來的架構簡化（28:00–36:38） <a class="header-anchor" href="#opus-4-6-帶來的架構簡化-28-00–36-38" aria-label="Permalink to &quot;Opus 4.6 帶來的架構簡化（28:00–36:38）&quot;">​</a></h3><p>原本複雜的設計（每 sprint 都跑 evaluator）在 Opus 4.6 下可以大幅簡化：</p><ul><li>模型能在 2 小時連續 build 中保持連貫性</li><li>不再需要強制 per-sprint 評估</li><li>一個連續 session 足以處理很長的建構任務</li><li>成本也因簡化而下降約一半</li></ul><p>核心 takeaway：harness 不會消失，而是隨模型能力演化——找到模型弱點、用 harness 填補、訓練模型吸收這個能力、再移除。</p><h3 id="q-a-精華-36-38–01-07-44" tabindex="-1">Q&amp;A 精華（36:38–01:07:44） <a class="header-anchor" href="#q-a-精華-36-38–01-07-44" aria-label="Permalink to &quot;Q&amp;A 精華（36:38–01:07:44）&quot;">​</a></h3><p><strong>評估器 rubric 是 per-project 還是可重用？</strong> 目標是可重用——找出跨模型的共通弱點。</p><p><strong>Context smart zone / Ralph Loop 還有意義嗎？</strong> Andrew 和 Ash 認為這是暫時問題；Opus 4.6 已能在更長 context 保持連貫，server-side compaction 接近解決 context rot。</p><p><strong>Human in the loop</strong>：最理想是完全自主；若需要人工介入，Hooks 是最自然的原語（stop condition → 交回人類 → 繼續 loop）。另一模式：跑 10 個平行版本，人工從成功的版本中挑選。</p><p><strong>讀 traces 的方法</strong>：不只是看 raw output，而是「把自己放進模型的視角」——像閉著眼睛瀏覽網頁、每 10 秒只能看一張靜態截圖。只有這樣才能真正理解為什麼模型做了某個決定，並調整下次的指令。</p><p><strong>Brownfield vs Greenfield</strong>：這個 harness 模式目前最適合 greenfield 新應用；brownfield 需要更多控制，但整個軟體開發生命週期（monitoring → issue generation → PR → review）都有應用空間。</p><hr><h2 id="逐字稿-含時間戳" tabindex="-1">逐字稿（含時間戳） <a class="header-anchor" href="#逐字稿-含時間戳" aria-label="Permalink to &quot;逐字稿（含時間戳）&quot;">​</a></h2><p><strong>[00:00 → 00:10]</strong> n thanks everyone for joining first session of the engineer conference of glad you&#39;re spending it with us. My name is Andrew. I&#39;m on the applied AI team based out of London working as a solution</p><p><strong>[00:10 → 00:29]</strong> solution architect with a lot of our digital native and industry customers. I&#39;m going to give history tour trip down memory lane but really with the focus on all the things we&#39;ve shipped that lead to agents being able to run for multiple hours or days at a time. I&#39;ll hand over to the state of the art.</p><p><strong>[00:29 → 00:54]</strong> Right speach. Right. Okay, so a little quote on Twitter from Boris, the creator of CloudCode. This was on the one year anniversary of CloudCode, basically saying a year ago Cloud was struggling to write bash commands and escaping strings and it could run for 20 minutes at a time. We&#39;re now at the point where almost all of CloudCode is being written by CloudCode and it can run effectively for days at a time.</p><p><strong>[00:54 → 01:18]</strong> Bush or the big, big swing over just the course of a year and walk through-through that history little bit now but just to sort of frame the problem out like why why is it that it&#39;s difficult for these agents to run for a period of time. I think broadly there&#39;s three big buckets. Some are more intuitive than others.</p><p><strong>[01:18 → 01:19]</strong> 我們要 milestones</p><p><strong>[01:19 → 01:19]</strong> windows very much</p><p><strong>[01:19 → 01:20]</strong> fine night</p><p><strong>[01:20 → 01:20]</strong> so you start</p><p><strong>[01:20 → 01:21]</strong> a new session</p><p><strong>[01:22 → 01:22]</strong> neesha</p><p><strong>[01:22 → 01:23]</strong> Asian has to start</p><p><strong>[01:23 → 01:24]</strong> from scratch</p><p><strong>[01:24 → 01:24]</strong> so you need</p><p><strong>[01:24 → 01:24]</strong> some sort of decid</p><p><strong>[01:24 → 01:25]</strong> of memory component</p><p><strong>[01:26 → 01:27]</strong> also as you&#39;re working</p><p><strong>[01:27 → 01:28]</strong> through a context</p><p><strong>[01:28 → 01:28]</strong> windows</p><p><strong>[01:28 → 01:29]</strong> this notion of context</p><p><strong>[01:29 → 01:30]</strong> planets so</p><p><strong>[01:30 → 01:31]</strong> this less coherence</p><p><strong>[01:31 → 01:32]</strong> as you&#39;re</p><p><strong>[01:32 → 01:33]</strong> you&#39;re getting deeper</p><p><strong>[01:33 → 01:33]</strong> into that session</p><p><strong>[01:34 → 01:35]</strong> also you might get</p><p><strong>[01:35 → 01:37]</strong> to the point where</p><p><strong>[01:37 → 01:38]</strong> the model actually</p><p><strong>[01:38 → 01:39]</strong> exhibits was called</p><p><strong>[01:39 → 01:40]</strong> contestance anxiety</p><p><strong>[01:40 → 01:41]</strong> so it gets kind</p><p><strong>[01:41 → 01:42]</strong> of nervous as it reaches</p><p><strong>[01:42 → 01:43]</strong> the end of its contacts</p><p><strong>[01:43 → 01:43]</strong> when known warning</p><p><strong>[01:43 → 01:44]</strong> just quickly</p><p><strong>[01:44 → 01:45]</strong> how to</p><p><strong>[01:45 → 01:46]</strong> shEPERS</p><p><strong>[01:46 → 02:04]</strong> 这 kind of leads into planning, so in general that great planning just out of the box, they might try and do everything in just one shot or for example they might build half a feature and then stop or they might just run out of context altogether and sort of leave a half finished app built.</p><p><strong>[02:04 → 02:09]</strong> But then maybe less intuitively models are really bad at judging their own output.</p><p><strong>[02:09 → 02:16]</strong> So I know, we all know that models can be authentic and sort of tell you what you want to hear, but this applies as well to coding tasks.</p><p><strong>[02:16 → 02:24]</strong> So it might look at a feature and see that it&#39;s sort of half baked or a little bit implemented and say, yeah, okay, that looks done and then we&#39;ll move on to the next thing.</p><p><strong>[02:24 → 02:29]</strong> Or it might build a feature like a button, but actually the back end doesn&#39;t exist for it.</p><p><strong>[02:29 → 02:32]</strong> There&#39;s sort of nothing behind that, but it looks like the feature is done.</p><p><strong>[02:32 → 02:38]</strong> So I know Ash will talk quite extensively of some of the new techniques we have to help with this.</p><p><strong>[02:38 → 02:42]</strong> Specifically, so models can become better at judging their own output.</p><p><strong>[02:42 → 02:46]</strong> So there&#39;s two ways really we can fix these things.</p><p><strong>[02:46 → 02:48]</strong> The first one is obviously the model.</p><p><strong>[02:48 → 02:51]</strong> So baking it all into the model weights themselves.</p><p><strong>[02:51 → 02:54]</strong> And I&#39;m sure you&#39;ve all seen this meter chart.</p><p><strong>[02:54 → 03:01]</strong> It&#39;s basically how long can an agent run for with a minimal scaffold where it&#39;s completing 50% of the tasks.</p><p><strong>[03:01 → 03:05]</strong> And you&#39;ll see from opus 3.7, it&#39;s around one hour.</p><p><strong>[03:06 → 03:11]</strong> The second thing that you can do is, of course, make changes to the harness itself.</p><p><strong>[03:11 → 03:20]</strong> So this is the scaffolding around the model and agent SDK, which ships with all the primitives that we&#39;ve been building over time.</p><p><strong>[03:20 → 03:26]</strong> So there&#39;s the core agent loop itself, where you have Claude model that&#39;s determining what to do with the model.</p><p><strong>[03:35 → 03:40]</strong> So you can do what tools to run, maybe it&#39;s pulling in some tools from MCP servers.</p><p><strong>[03:40 → 03:42]</strong> It might delegate some tasks to a subagent.</p><p><strong>[03:42 → 03:47]</strong> It&#39;s bringing in all the context from things like Claude.md or the skills that are loaded or slash commands.</p><p><strong>[03:47 → 03:49]</strong> There&#39;s a whole permission system.</p><p><strong>[03:49 → 03:53]</strong> And this will change over time as well as the models get better and improve.</p><p><strong>[03:53 → 03:56]</strong> But these are sort of the core primitives that we&#39;re working with.</p><p><strong>[03:56 → 04:01]</strong> And then of course you use this framework to build your own harness for whatever it is you&#39;re trying to do,</p><p><strong>[04:01 → 04:06]</strong> such as some of the things that Ash will show later on when we get into more long running agents.</p><p><strong>[04:06 → 04:11]</strong> I think what&#39;s also interesting is just looking back at the last year of releases</p><p><strong>[04:11 → 04:17]</strong> is that when we&#39;ve released a model, we&#39;ve also released a lot of harness changes alongside the models.</p><p><strong>[04:17 → 04:20]</strong> So really these things are co-evolving together.</p><p>[... 共 1553 segments，完整逐字稿見 /tmp/claude-scratch/out/easycompany.txt ...]</p>',110)])])}const c=o(r,[["render",a]]);export{d as __pageData,c as default};
